32:export type UserFacingFailure = "actionable" | "closed" | "pending";
33:
34:/** Which of the three a classified failure belongs to. */
35:export function userFacingFailure(outcome: FailureOutcome): UserFacingFailure {
36:  switch (outcome) {
37:    case "needs_login":
38:    case "needs_answer":
39:      return "actionable";
40:    case "posting_gone":
41:      return "closed";
42:    case "wall":
43:    case "our_bug":
44:    case "unknown":
45:      return "pending";
46:  }
47:}
48:
49:/** Badge tone vocabulary, shared by the state badges and the failure boxes. */
50:export type StateTone = "ok" | "warn" | "danger" | "accent" | "off";
51:
52:/**
53: * Visual tone for an application state.
54: *
55: * `error` is deliberately `off` and not `danger`: the red badge was the loudest
56: * half of the problem this file exists to fix, and every `error` row is either
57: * something the reader can act on (which `presentedState` paints `warn`) or
58: * something we are still working on (which is not an alarm).
59: */
60:export function stateTone(state: string): StateTone {
61:  switch (state) {
62:    case "applied":
63:    case "submitted":
64:    case "offer":
65:      return "ok";
66:    case "approved":
67:    case "interviewing":
68:      return "accent";
69:    case "queued_review":
70:    case "applying":
71:      return "warn";
72:    case "no_fit":
73:    case "rejected_by_user":
74:    case "rejected_by_company":
75:    case "withdrawn":
76:      return "danger";
77:    default:
78:      return "off";
79:  }
80:}
81:
82:/** The label key the reader sees, and the colour it wears. */
83:export interface PresentedState {
84:  /** `"pending"` for an errored row; otherwise the state's own token. */
85:  key: string;
86:  tone: StateTone;
87:}
88:
89:/**
90: * How one application's state is shown to the candidate.
91: *
92: * Every state but `error` passes through unchanged. An `error` row becomes
93: * `pending` — one word for all three outcomes, because a candidate reading a
94: * list does not need three — and only the tone separates "there is something
95: * for you here" from "we are on it".
96: */
97:export function presentedState(
98:  state: string,
99:  failureReason: string | null | undefined,
100:): PresentedState {
101:  if (state !== "error") return { key: state, tone: stateTone(state) };
102:  const facing = userFacingFailure(classifyFailure(failureReason));
103:  return { key: "pending", tone: facing === "actionable" ? "warn" : "off" };
104:}
